function resolvePortableDataDir() {
  if (process.env.SOUNDCLOUD_PORTABLE_DIR) {
    return path.resolve(process.env.SOUNDCLOUD_PORTABLE_DIR);
  }
  if (process.env.APPIMAGE) {
    const appImageDir = path.dirname(process.env.APPIMAGE);
    const sidecarDir = path.join(appImageDir, 'soundcloud-portable-data');
    try {
      fs.mkdirSync(sidecarDir, { recursive: true });
      return sidecarDir;
    } catch (err) {}
  }
  const localPortableDir = path.join(path.dirname(app.getPath('exe')), 'portable-data');
  if (process.env.SOUNDCLOUD_PORTABLE === '1' || fs.existsSync(localPortableDir)) {
    try {
      fs.mkdirSync(localPortableDir, { recursive: true });
      return localPortableDir;
    } catch (err) {}
  }
  const repoPortableDir = path.join(__dirname, 'portable-data');
  if (process.env.SOUNDCLOUD_PORTABLE === '1') {
    try {
      fs.mkdirSync(repoPortableDir, { recursive: true });
      return repoPortableDir;
    } catch (err) {}
  }
  return null;
}

const portableDir = resolvePortableDataDir();
