function getAssetPath(filename) {
  const candidates = [
    path.join(__dirname, 'assets', filename),
    path.join(process.resourcesPath || __dirname, 'assets', filename)
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) return candidate;
  }
  return path.join(__dirname, 'assets', filename);
}

function getResourceFilePath(relPath) {
  const candidates = [
    path.join(__dirname, relPath),
    path.join(process.resourcesPath || __dirname, relPath)
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) return candidate;
  }
  return path.join(__dirname, relPath);
}

function writeStateFileAndBroadcast() {
  try {
    fs.writeFileSync(STATE_FILE, JSON.stringify(currentTrack), 'utf-8');
  } catch (e) {}
}

function broadcastSettings() {
  if (win && !win.isDestroyed()) {
    win.webContents.send('app:settings-updated', store.store);
  }
}

// ------------------------------------------------------------------
// Official SoundCloud Desktop Icons & Automatic Removal of Unwanted Top Bar Extension
// ------------------------------------------------------------------
function installLinuxDesktopAndIcons() {
  if (process.platform !== 'linux') return;
  try {
    const homeDir = process.env.HOME || app.getPath('home');
    const iconSrc = getAssetPath('icon.png');
    if (!fs.existsSync(iconSrc)) return;

    const sizes = ['64x64', '128x128', '256x256', '512x512'];
    for (const sz of sizes) {
      const dir = path.join(homeDir, '.local', 'share', 'icons', 'hicolor', sz, 'apps');
      fs.mkdirSync(dir, { recursive: true });
      fs.copyFileSync(iconSrc, path.join(dir, 'soundcloud-electron.png'));
      fs.copyFileSync(iconSrc, path.join(dir, 'com.soundcloud.Client.png'));
    }

    const pixmapsDir = path.join(homeDir, '.local', 'share', 'pixmaps');
    fs.mkdirSync(pixmapsDir, { recursive: true });
    fs.copyFileSync(iconSrc, path.join(pixmapsDir, 'soundcloud-electron.png'));
    fs.copyFileSync(iconSrc, path.join(pixmapsDir, 'com.soundcloud.Client.png'));

    // Only write local .desktop if not running inside Flatpak sandbox
    if (!process.env.FLATPAK_ID) {
      const appsDir = path.join(homeDir, '.local', 'share', 'applications');
      fs.mkdirSync(appsDir, { recursive: true });
      const execCmd = `"${process.execPath}" "${__dirname}" --no-sandbox %U`;
      const desktopContent = [
        '[Desktop Entry]',
        'Name=SoundCloud',
        'GenericName=Music Player',
        'Comment=SoundCloud Desktop Client',
        `Exec=${execCmd}`,
        'Terminal=false',
        'Type=Application',
        'Icon=com.soundcloud.Client',
        'StartupWMClass=com.soundcloud.Client',
        'Categories=AudioVideo;Audio;Player;',
        ''
      ].join('\n');

      const desktopFile = path.join(appsDir, 'soundcloud-electron.desktop');
      fs.writeFileSync(desktopFile, desktopContent, 'utf-8');
      try { fs.chmodSync(desktopFile, 0o755); } catch (e) {}
    }
  } catch (e) {}
}

function removeGnomeTopBarExtension() {
  if (process.platform !== 'linux') return;
  installLinuxDesktopAndIcons();
  try {
    const extUuid = 'soundcloud-panel@soundcloud.electron';
    try {
      execSync(`gnome-extensions disable ${extUuid}`, { stdio: 'ignore' });
    } catch (e) {}
    try {
      execSync(`gnome-extensions uninstall ${extUuid}`, { stdio: 'ignore' });
    } catch (e) {}
    const homeDir = process.env.HOME || app.getPath('home');
    const targetDir = path.join(homeDir, '.local', 'share', 'gnome-shell', 'extensions', extUuid);
    if (fs.existsSync(targetDir)) {
      fs.rmSync(targetDir, { recursive: true, force: true });
    }
    const localExtDir = path.join(__dirname, 'gnome-extension');
    if (fs.existsSync(localExtDir)) {
      fs.rmSync(localExtDir, { recursive: true, force: true });
    }
  } catch (err) {}
}

function startMprisBridge() {
  if (process.platform !== 'linux' || mprisProcess) return;
  const scriptPath = getResourceFilePath('mpris_bridge.py');
  if (!fs.existsSync(scriptPath)) return;

  try {
    mprisProcess = spawn('python3', [scriptPath], {
      stdio: 'ignore',
      detached: false
    });
    mprisProcess.on('exit', () => {
      mprisProcess = null;
    });
  } catch (err) {
    mprisProcess = null;
  }
}

function getWallpaperMimeType(filePath) {
  const ext = path.extname(filePath || '').toLowerCase();
  const map = {
    '.mp4': 'video/mp4',
    '.m4v': 'video/mp4',
    '.webm': 'video/webm',
    '.mkv': 'video/x-matroska',
    '.avi': 'video/x-msvideo',
    '.ogv': 'video/ogg',
    '.gif': 'image/gif',
    '.webp': 'image/webp',
    '.apng': 'image/apng',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.svg': 'image/svg+xml'
  };
  return map[ext] || 'application/octet-stream';
}

function startLocalControlServer() {
  if (controlServer) return;
  try {
    controlServer = http.createServer((req, res) => {
      const url = req.url || '/';

      if (url.startsWith('/wallpaper-stream')) {
        try {
          const wpPath = store.get('wallpaperFilePath') || '';
          if (!wpPath || !fs.existsSync(wpPath)) {
            res.statusCode = 404;
            res.end('Not found');
            return;
          }
          const stat = fs.statSync(wpPath);
          const totalSize = stat.size;
          const mimeType = getWallpaperMimeType(wpPath);
          res.setHeader('Access-Control-Allow-Origin', '*');
          res.setHeader('Access-Control-Allow-Private-Network', 'true');
          res.setHeader('Cross-Origin-Resource-Policy', 'cross-origin');
          res.setHeader('Accept-Ranges', 'bytes');
          res.setHeader('Cache-Control', 'no-cache');

          const range = req.headers.range;
          if (range) {
            const parts = range.replace(/bytes=/, '').split('-');
            const start = parseInt(parts[0], 10) || 0;
            const end = parts[1] ? parseInt(parts[1], 10) : Math.min(totalSize - 1, start + 4 * 1024 * 1024);
            const chunkSize = end - start + 1;
            res.writeHead(206, {
              'Content-Range': `bytes ${start}-${end}/${totalSize}`,
              'Content-Length': chunkSize,
              'Content-Type': mimeType
            });
            const stream = fs.createReadStream(wpPath, { start, end });
            req.on('close', () => {
              try { stream.destroy(); } catch (e) {}
            });
            stream.pipe(res);
          } else {
            res.writeHead(200, {
              'Content-Length': totalSize,
              'Content-Type': mimeType
            });
            const stream = fs.createReadStream(wpPath);
            req.on('close', () => {
              try { stream.destroy(); } catch (e) {}
            });
            stream.pipe(res);
          }
        } catch (err) {
          res.statusCode = 500;
          res.end('Error');
        }
        return;
      }

      res.setHeader('Content-Type', 'application/json');

      if (url === '/state') {
        res.end(JSON.stringify(currentTrack));
        return;
      }
      if (url.startsWith('/action/playpause')) {
        executeMediaControl(['.playControls__play', '.playControl']);
        res.end(JSON.stringify({ ok: true }));
        return;
      }
      if (url.startsWith('/action/next')) {
        executeMediaControl(['.skipControl__next']);
        res.end(JSON.stringify({ ok: true }));
        return;
      }
      if (url.startsWith('/action/prev')) {
        executeMediaControl(['.skipControl__previous']);
        res.end(JSON.stringify({ ok: true }));
        return;
      }
      if (url.startsWith('/action/repeat')) {
        executeMediaControl(['.repeatControl']);
        res.end(JSON.stringify({ ok: true }));
        return;
      }
      if (url.startsWith('/action/shuffle')) {
        executeMediaControl(['.shuffleControl']);
        res.end(JSON.stringify({ ok: true }));
        return;
      }
      if (url.startsWith('/action/focus')) {
        if (win && !win.isDestroyed()) {
          win.show();
          if (win.isMinimized()) win.restore();
          win.focus();
        }
        res.end(JSON.stringify({ ok: true }));
        return;
      }
      if (url.startsWith('/action/quit')) {
        app.isQuitting = true;
        app.quit();
        res.end(JSON.stringify({ ok: true }));
        return;
      }

      res.statusCode = 404;
      res.end(JSON.stringify({ ok: false }));
    });

    controlServer.on('error', () => {});
    controlServer.listen(CONTROL_PORT, '127.0.0.1');
  } catch (e) {}
}

// ------------------------------------------------------------------
// Responsive Fullscreen / Maximize View Sizing Across All Resolutions
// ------------------------------------------------------------------
const TOP_BAR_HEIGHT = 40;

function resizeView(explicitWidth, explicitHeight) {
  if (!win || win.isDestroyed() || !view || view.webContents.isDestroyed()) return;

  if (
    typeof explicitWidth === 'number' &&
    explicitWidth > 100 &&
    typeof explicitHeight === 'number' &&
    explicitHeight > 100
  ) {
    lastRendererWidth = Math.round(explicitWidth);
    lastRendererHeight = Math.round(explicitHeight);
  } else {
    const contentBounds = win.getContentBounds();
    const winBounds = win.getBounds();
    const [cw, ch] = win.getContentSize();
    const bestW = Math.max(cw || 0, contentBounds.width || 0, winBounds.width || 0, lastRendererWidth || 0);
    const bestH = Math.max(ch || 0, contentBounds.height || 0, winBounds.height || 0, lastRendererHeight || 0);
    if (bestW > 100) lastRendererWidth = bestW;
    if (bestH > 100) lastRendererHeight = bestH;
  }

  view.setBounds({
    x: 0,
    y: TOP_BAR_HEIGHT,
    width: Math.max(200, lastRendererWidth),
    height: Math.max(120, lastRendererHeight - TOP_BAR_HEIGHT)
  });
}

function scheduleMultiTickResize() {
  resizeView();
  setTimeout(() => resizeView(), 50);
  setTimeout(() => resizeView(), 150);
  setTimeout(() => resizeView(), 320);
}

// ------------------------------------------------------------------
// Main Window & SoundCloud BrowserView
// ------------------------------------------------------------------
function createWindow() {
  const iconPngPath = getAssetPath('icon.png');
  const appIconImage = nativeImage.createFromPath(iconPngPath);

  win = new BrowserWindow({
    width: 1240,
    height: 820,
    minWidth: 720,
    minHeight: 480,
    frame: false,
    backgroundColor: '#0e0e10',
    icon: appIconImage.isEmpty() ? iconPngPath : appIconImage,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      spellcheck: false,
      preload: path.join(__dirname, 'preload.js')
    }
  });

  if (!appIconImage.isEmpty() && typeof win.setIcon === 'function') {
    try { win.setIcon(appIconImage); } catch (e) {}
  }

  Menu.setApplicationMenu(null);
  win.loadFile(path.join(__dirname, 'index.html'));

  view = new BrowserView({
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      spellcheck: false,
      backgroundThrottling: false,
      preload: path.join(__dirname, 'preload-view.js')
    }
  });

  win.setBrowserView(view);
  try {
    view.setAutoResize({ width: true, height: true, horizontal: false, vertical: false });
  } catch (e) {}
  scheduleMultiTickResize();

  win.on('resize', scheduleMultiTickResize);
  win.on('maximize', scheduleMultiTickResize);
  win.on('unmaximize', scheduleMultiTickResize);
  win.on('enter-full-screen', scheduleMultiTickResize);
  win.on('leave-full-screen', scheduleMultiTickResize);

  view.webContents.setUserAgent(chromeUA);
  view.webContents.loadURL('https://soundcloud.com');

  function buildPopupOptions() {
    return {
      action: 'allow',
      overrideBrowserWindowOptions: {
        width: 540,
        height: 700,
        frame: true,
        modal: false,
        parent: null,
        autoHideMenuBar: true,
        icon: iconPngPath,
        webPreferences: {
          nodeIntegration: false,
          contextIsolation: true,
          preload: path.join(__dirname, 'preload-view.js')
        }
      }
    };
  }

  function configurePopupWindow(childWindow) {
    try {
      childWindow.setParentWindow(null);
      childWindow.setMenuBarVisibility(false);
      // Set Firefox Linux User-Agent from millisecond zero on auth popups so
      // Google / Apple / SoundCloud OAuth never detects an embedded Chromium mismatch
      childWindow.webContents.setUserAgent(firefoxUA);
    } catch (e) {}

    const applyAuthUserAgent = (url = '') => {
      if (childWindow.isDestroyed()) return;
      if (url.includes('google.com') || url.includes('accounts.youtube.com')) {
        childWindow.webContents.setUserAgent(firefoxUA);
      }
    };

    childWindow.webContents.on('will-navigate', (_e, url) => applyAuthUserAgent(url));
    childWindow.webContents.on('did-start-navigation', (_e, url) => applyAuthUserAgent(url));

    childWindow.webContents.setWindowOpenHandler(() => buildPopupOptions());
    childWindow.webContents.on('did-create-window', (nestedChild) => {
      configurePopupWindow(nestedChild);
    });

    childWindow.on('closed', () => {
      setTimeout(() => {
        if (win && !win.isDestroyed()) {
          win.focus();
        }
        if (view && !view.webContents.isDestroyed()) {
          view.webContents.focus();
          view.webContents
            .executeJavaScript(`
              (() => {
                document.querySelectorAll('button[disabled], input[disabled]').forEach((el) => {
                  el.removeAttribute('disabled');
                  el.classList.remove('sc-button-disabled');
                });
                if (document.body) {
                  document.body.style.pointerEvents = 'auto';
                }
              })();
            `)
            .catch(() => {});
        }
        scheduleMultiTickResize();
      }, 60);
    });
  }

  view.webContents.setWindowOpenHandler(() => buildPopupOptions());
  view.webContents.on('did-create-window', (childWindow) => {
    configurePopupWindow(childWindow);
  });

  win.on('close', (event) => {
    if (!app.isQuitting && store.get('closeToTray') && tray) {
      event.preventDefault();
      win.hide();
      return false;
    }
    app.isQuitting = true;
    return true;
  });

  win.on('closed', () => {
    cleanup();
  });

  const handleKeyShortcuts = (event, input) => {
    if (input.type !== 'keyDown') return;
    if (input.control && input.shift && input.key.toLowerCase() === 'i') {
      view.webContents.toggleDevTools();
      event.preventDefault();
    } else if (input.key === 'F11') {
      if (win && !win.isDestroyed()) {
        win.setFullScreen(!win.isFullScreen());
        scheduleMultiTickResize();
      }
      event.preventDefault();
    }
  };

  view.webContents.on('before-input-event', handleKeyShortcuts);
  win.webContents.on('before-input-event', handleKeyShortcuts);

  view.webContents.on('did-finish-load', () => {
    startTrackMonitoring();
    scheduleMultiTickResize();
  });

  createTray(win);
}

